          "trechos": [
            "Ebe23d4e8dd03da4a:0:699"
          ],
          "condicoes": [
            "para todos os modos de falha em análise no programa"
          ],
          "limites": [
            "o trecho não define metodologia detalhada para calcular POR e COR",
            "não fornece periodicidades fechadas de revisão"
          ]
        },
        {
          "proposicao": "A eficácia dos métodos de monitoramento e inspeção deve ser aferida pela comparação entre falhas ocorridas e métodos inicialmente definidos.",
          "trechos": [
            "Ebe23d4e8dd03da4a:0:699"
          ],
          "condicoes": [
            "com base em histórico de monitoramento, inspeção e falhas ocorridas"
          ],
          "limites": [
            "o trecho não estabelece indicadores de desempenho ou critérios de aceitação"
          ]
        },
        {
          "proposicao": "Devem existir procedimentos tanto para reavaliar o programa a partir dos resultados obtidos quanto para atualizar o PMI segundo critérios prescritos.",
          "trechos": [
            "Ebe23d4e8dd03da4a:699:1399"
          ],
          "condicoes": [
            "aplicável aos modos de falha sujeitos a monitoramento e inspeção"
          ],
          "limites": [
            "os critérios prescritos não aparecem no trecho fornecido",
            "a sigla PMI é mencionada no contexto da fonte, mas o conteúdo recuperado não detalha integralmente sua estrutura"
          ]
        }
      ]
